css:
.rrt-container {
    padding: 28px;
    background: linear-gradient(180deg, #f5efe6 0%, #ece2cf 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1c2440;
}

/* ================ HEADER ================ */
.rrt-container .rrt-header {
    background: linear-gradient(135deg, #0f1d3a 0%, #1c2f5a 100%);
    color: #f5efe6;
    border-radius: 16px;
    padding: 28px 32px;
    margin-bottom: 28px;
    box-shadow: 0 12px 32px rgba(15,29,58,0.25);
    border-bottom: 4px solid #c4a35a;
}
.rrt-container .rrt-title-row {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 16px;
    flex-wrap: wrap;
}
.rrt-container .rrt-header h1 {
    font-size: 1.6rem;
    font-weight: 700;
    letter-spacing: 0.01em;
    margin: 0;
    color: #f5efe6;
}
.rrt-container .rrt-period-counter {
    background: rgba(196,163,90,0.18);
    border: 1px solid rgba(196,163,90,0.4);
    border-radius: 999px;
    padding: 6px 16px;
    font-size: 0.85rem;
    letter-spacing: 0.04em;
    color: #f5efe6;
    white-space: nowrap;
}
.rrt-container .rrt-period-counter span:not([data-i18n]) {
    font-weight: 700;
    color: #e6c987;
}
.rrt-container .rrt-subtitle {
    margin-top: 10px;
    color: #c9d4ea;
    font-style: italic;
    font-size: 0.95rem;
    line-height: 1.5;
}

/* ================ BRIEFING ================ */
.rrt-container .rrt-briefing {
    background: #ffffff;
    border-left: 5px solid #c4a35a;
    border-radius: 12px;
    padding: 20px 24px;
    margin-bottom: 28px;
    box-shadow: 0 4px 14px rgba(15,29,58,0.06);
}
.rrt-container .rrt-briefing-title {
    font-weight: 700;
    color: #0f1d3a;
    font-size: 1.1rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 8px;
}
.rrt-container .rrt-briefing-text {
    color: #2d3a5e;
    line-height: 1.6;
    font-size: 0.98rem;
}
.rrt-container .rrt-briefing-text b { color: #0f1d3a; }

/* ================ SIBLINGS ================ */
.rrt-container .rrt-siblings-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    margin-bottom: 28px;
}
.rrt-container .rrt-sibling-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 22px;
    box-shadow: 0 6px 18px rgba(15,29,58,0.08);
    border-top: 4px solid #cbd2e0;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.rrt-container .rrt-sibling-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 24px rgba(15,29,58,0.12);
}
.rrt-container .rrt-sibling-sara { border-top-color: #c4a35a; }
.rrt-container .rrt-sibling-mateo { border-top-color: #3a6ea5; }
.rrt-container .rrt-sibling-carmen { border-top-color: #7a8a5e; }

.rrt-container .rrt-sibling-head { margin-bottom: 14px; }
.rrt-container .rrt-sibling-name {
    font-size: 1.3rem;
    font-weight: 700;
    color: #0f1d3a;
    letter-spacing: 0.01em;
}
.rrt-container .rrt-sibling-meta {
    color: #6a7592;
    font-size: 0.82rem;
    margin-top: 2px;
    letter-spacing: 0.02em;
}
.rrt-container .rrt-sibling-value {
    font-size: 2.1rem;
    font-weight: 800;
    color: #0f1d3a;
    line-height: 1.1;
    letter-spacing: -0.01em;
}
.rrt-container .rrt-sibling-delta {
    font-size: 0.88rem;
    font-weight: 600;
    margin-top: 4px;
    min-height: 1.2em;
    color: #6a7592;
}
.rrt-container .rrt-sibling-delta.up { color: #2f7a3e; }
.rrt-container .rrt-sibling-delta.down { color: #b53f3f; }

/* allocation bar */
.rrt-container .rrt-allocation-bar {
    display: flex;
    height: 10px;
    border-radius: 999px;
    overflow: hidden;
    margin-top: 16px;
    background: #ece2cf;
}
.rrt-container .rrt-bar-eq { background: linear-gradient(90deg, #c4a35a, #d8b97a); transition: width 0.4s ease; }
.rrt-container .rrt-bar-bonds { background: linear-gradient(90deg, #3a6ea5, #5b8dc4); transition: width 0.4s ease; }
.rrt-container .rrt-bar-cash { background: linear-gradient(90deg, #7a8a5e, #9aaa7e); transition: width 0.4s ease; }

.rrt-container .rrt-allocation-stats {
    display: flex;
    gap: 8px;
    margin-top: 12px;
    flex-wrap: wrap;
}
.rrt-container .rrt-pill {
    font-size: 0.78rem;
    padding: 4px 10px;
    border-radius: 999px;
    background: #f5efe6;
    color: #2d3a5e;
    font-weight: 600;
}
.rrt-container .rrt-pill-eq { background: rgba(196,163,90,0.18); color: #6e5424; }
.rrt-container .rrt-pill-bonds { background: rgba(58,110,165,0.15); color: #1c4476; }
.rrt-container .rrt-pill-cash { background: rgba(122,138,94,0.18); color: #41522a; }

/* ================ PANELS ================ */
.rrt-container .rrt-panel {
    background: #ffffff;
    border-radius: 14px;
    padding: 24px 28px;
    margin-bottom: 28px;
    box-shadow: 0 6px 18px rgba(15,29,58,0.08);
}
.rrt-container .rrt-panel-head h3 {
    margin: 0 0 4px 0;
    color: #0f1d3a;
    font-size: 1.15rem;
    font-weight: 700;
}
.rrt-container .rrt-panel-sub {
    color: #6a7592;
    font-size: 0.88rem;
    margin-bottom: 20px;
}

/* asset table */
.rrt-container .rrt-asset-table {
    border: 1px solid #e2dac9;
    border-radius: 10px;
    overflow: hidden;
    margin-bottom: 22px;
    background: #fbf6ec;
}
.rrt-container .rrt-asset-row {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 3fr;
    gap: 12px;
    padding: 12px 16px;
    border-bottom: 1px solid #e2dac9;
    font-size: 0.9rem;
    color: #2d3a5e;
    align-items: center;
}
.rrt-container .rrt-asset-row:last-child { border-bottom: none; }
.rrt-container .rrt-asset-header {
    background: #0f1d3a;
    color: #c9d4ea;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.74rem;
    letter-spacing: 0.06em;
}
.rrt-container .rrt-dot {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    margin-right: 6px;
    vertical-align: middle;
}
.rrt-container .rrt-dot-eq { background: #c4a35a; }
.rrt-container .rrt-dot-bonds { background: #3a6ea5; }
.rrt-container .rrt-dot-cash { background: #7a8a5e; }

/* builder grid */
.rrt-container .rrt-builder-grid { display: flex; flex-direction: column; gap: 14px; }
.rrt-container .rrt-builder-row {
    display: grid;
    grid-template-columns: 200px 1fr;
    gap: 16px;
    align-items: center;
    padding: 12px 16px;
    background: #fbf6ec;
    border-radius: 10px;
    border: 1px solid #e2dac9;
}
.rrt-container .rrt-builder-label {
    font-weight: 700;
    color: #0f1d3a;
    font-size: 1rem;
}
.rrt-container .rrt-tag {
    display: inline-block;
    background: #c4a35a;
    color: #241a05;
    border-radius: 999px;
    padding: 2px 10px;
    font-size: 0.7rem;
    font-weight: 600;
    margin-left: 6px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}
.rrt-container .rrt-builder-inputs {
    display: flex;
    gap: 10px;
    align-items: center;
    flex-wrap: wrap;
}
.rrt-container .rrt-builder-inputs label {
    font-size: 0.82rem;
    color: #6a7592;
    margin: 0;
    font-weight: 600;
    letter-spacing: 0.02em;
}
.rrt-container .rrt-builder-inputs input[type="number"] {
    background: #ffffff;
    border: 1.5px solid #c9d4ea;
    color: #0f1d3a;
    border-radius: 8px;
    padding: 8px 10px;
    width: 78px;
    font-size: 0.95rem;
    font-weight: 600;
    text-align: right;
    transition: border-color 0.2s ease;
}
.rrt-container .rrt-builder-inputs input[type="number"]:focus {
    outline: none;
    border-color: #c4a35a;
    box-shadow: 0 0 0 3px rgba(196,163,90,0.2);
}
.rrt-container .rrt-sum {
    font-weight: 700;
    color: #2f7a3e;
    margin-left: auto;
    padding: 6px 12px;
    background: rgba(47,122,62,0.12);
    border-radius: 8px;
    font-size: 0.9rem;
    min-width: 70px;
    text-align: center;
}
.rrt-container .rrt-sum.bad {
    color: #b53f3f;
    background: rgba(181,63,63,0.12);
}

.rrt-container .rrt-rule-of-thumb {
    margin-top: 18px;
    padding: 12px 16px;
    background: rgba(196,163,90,0.12);
    border-left: 3px solid #c4a35a;
    border-radius: 6px;
    color: #2d3a5e;
    font-size: 0.9rem;
    line-height: 1.5;
}

/* ================ CRASH PANEL ================ */
.rrt-container .rrt-crash-banner {
    background: linear-gradient(135deg, #6b1a1a, #8b2a2a);
    color: #fbf6ec;
    border-radius: 10px;
    padding: 18px 22px;
    font-size: 0.96rem;
    line-height: 1.55;
    margin-bottom: 22px;
    border-left: 4px solid #c4a35a;
}
.rrt-container .rrt-action-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-bottom: 18px;
}
.rrt-container .rrt-action-card {
    background: #fbf6ec;
    border: 1px solid #e2dac9;
    border-radius: 12px;
    padding: 18px;
    border-top: 4px solid #cbd2e0;
}
.rrt-container .rrt-action-card.rrt-sibling-sara { border-top-color: #c4a35a; }
.rrt-container .rrt-action-card.rrt-sibling-mateo { border-top-color: #3a6ea5; }
.rrt-container .rrt-action-card.rrt-sibling-carmen { border-top-color: #7a8a5e; }
.rrt-container .rrt-action-name {
    font-weight: 700;
    color: #0f1d3a;
    font-size: 1.05rem;
    margin-bottom: 8px;
}
.rrt-container .rrt-action-meta {
    color: #6a7592;
    font-weight: 500;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}
.rrt-container .rrt-action-trough {
    font-size: 1.7rem;
    font-weight: 800;
    color: #b53f3f;
    line-height: 1.1;
}
.rrt-container .rrt-action-loss {
    color: #b53f3f;
    font-weight: 700;
    font-size: 0.95rem;
    margin-bottom: 14px;
}
.rrt-container .rrt-action-card label {
    display: block;
    font-size: 0.82rem;
    color: #6a7592;
    margin-bottom: 6px;
    font-weight: 600;
    letter-spacing: 0.02em;
}
.rrt-container .rrt-action-card select {
    width: 100%;
    background: #ffffff;
    border: 1.5px solid #c9d4ea;
    color: #0f1d3a;
    border-radius: 8px;
    padding: 9px 12px;
    font-size: 0.92rem;
    font-weight: 500;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.rrt-container .rrt-action-card select:focus {
    outline: none;
    border-color: #c4a35a;
    box-shadow: 0 0 0 3px rgba(196,163,90,0.2);
}
.rrt-container .rrt-action-card select option {
    background: #ffffff;
    color: #0f1d3a;
}
.rrt-container .rrt-news-strip {
    background: #1c2440;
    color: #c9d4ea;
    padding: 10px 18px;
    border-radius: 8px;
    font-size: 0.82rem;
    font-style: italic;
    letter-spacing: 0.02em;
}

/* ================ COMPARE PANEL ================ */
.rrt-container .rrt-compare-panel {
    background: #ffffff;
    border-radius: 14px;
    padding: 24px 28px;
    margin-bottom: 28px;
    box-shadow: 0 6px 18px rgba(15,29,58,0.08);
    border-top: 4px solid #c4a35a;
}
.rrt-container .rrt-compare-panel h3 {
    color: #0f1d3a;
    font-size: 1.1rem;
    font-weight: 700;
    margin: 0 0 16px 0;
}
.rrt-container .rrt-compare-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-bottom: 16px;
}
.rrt-container .rrt-compare-card {
    background: #fbf6ec;
    border: 1px solid #e2dac9;
    border-radius: 10px;
    padding: 16px;
    border-left: 4px solid #c4a35a;
}
.rrt-container .rrt-compare-card.rrt-sibling-mateo { border-left-color: #3a6ea5; }
.rrt-container .rrt-compare-card.rrt-sibling-carmen { border-left-color: #7a8a5e; }
.rrt-container .rrt-compare-card .rrt-compare-name {
    font-weight: 700;
    color: #0f1d3a;
    font-size: 1rem;
    margin-bottom: 10px;
}
.rrt-container .rrt-compare-row {
    display: flex;
    justify-content: space-between;
    padding: 6px 0;
    border-bottom: 1px solid #e2dac9;
    font-size: 0.9rem;
}
.rrt-container .rrt-compare-row:last-child { border-bottom: none; }
.rrt-container .rrt-compare-row.best { color: #2f7a3e; font-weight: 700; }
.rrt-container .rrt-compare-row.worst { color: #b53f3f; font-weight: 700; }
.rrt-container .rrt-compare-row.chosen {
    background: rgba(196,163,90,0.15);
    margin: 0 -8px;
    padding: 6px 8px;
    border-radius: 4px;
}
.rrt-container .rrt-compare-note {
    color: #2d3a5e;
    font-size: 0.9rem;
    line-height: 1.55;
    padding: 12px 16px;
    background: rgba(196,163,90,0.12);
    border-left: 3px solid #c4a35a;
    border-radius: 6px;
}

/* ================ ACTIONS ================ */
.rrt-container .rrt-actions {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-bottom: 24px;
    flex-wrap: wrap;
}
.rrt-container .btn-primary {
    background: linear-gradient(135deg, #0f1d3a, #1c2f5a);
    border: none;
    color: #f5efe6;
    border-radius: 10px;
    padding: 12px 28px;
    font-weight: 700;
    letter-spacing: 0.04em;
    font-size: 0.95rem;
    box-shadow: 0 4px 12px rgba(15,29,58,0.25);
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}
.rrt-container .btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(15,29,58,0.35);
    background: linear-gradient(135deg, #1c2f5a, #2a3f6a);
}
.rrt-container .btn-outline-secondary {
    background: transparent;
    border: 1.5px solid #6a7592;
    color: #2d3a5e;
    border-radius: 10px;
    padding: 10px 20px;
    font-weight: 600;
    transition: background 0.2s ease;
}
.rrt-container .btn-outline-secondary:hover {
    background: rgba(106,117,146,0.12);
    color: #0f1d3a;
}

/* ================ CHART ================ */
.rrt-container .rrt-chart-wrap {
    background: #ffffff;
    border-radius: 14px;
    padding: 22px;
    margin-bottom: 28px;
    box-shadow: 0 6px 18px rgba(15,29,58,0.08);
    height: 360px;
}

/* ================ HISTORY TABLE ================ */
.rrt-container .rrt-history {
    background: #ffffff;
    border-radius: 14px;
    padding: 22px;
    box-shadow: 0 6px 18px rgba(15,29,58,0.08);
}
.rrt-container .rrt-history h3 {
    color: #0f1d3a;
    font-size: 1.05rem;
    font-weight: 700;
    margin: 0 0 14px 0;
}
.rrt-container .rrt-history table {
    width: 100%;
    border-collapse: collapse;
    color: #2d3a5e;
    font-size: 0.9rem;
}
.rrt-container .rrt-history th {
    background: #0f1d3a;
    color: #c9d4ea;
    padding: 10px 12px;
    text-align: left;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.74rem;
    letter-spacing: 0.06em;
}
.rrt-container .rrt-history td {
    padding: 10px 12px;
    border-bottom: 1px solid #e2dac9;
}
.rrt-container .rrt-history tr:nth-child(even) td { background: #fbf6ec; }

/* ================ RESPONSIVE ================ */
@media (max-width: 768px) {
    .rrt-container { padding: 16px; }
    .rrt-container .rrt-siblings-grid { grid-template-columns: 1fr; }
    .rrt-container .rrt-action-grid { grid-template-columns: 1fr; }
    .rrt-container .rrt-compare-grid { grid-template-columns: 1fr; }
    .rrt-container .rrt-builder-row { grid-template-columns: 1fr; }
    .rrt-container .rrt-asset-row {
        grid-template-columns: 1fr 1fr;
        font-size: 0.82rem;
    }
    .rrt-container .rrt-asset-header { display: none; }
    .rrt-container .rrt-header h1 { font-size: 1.25rem; }
    .rrt-container .rrt-sibling-value { font-size: 1.7rem; }
}


/* --- EQIL 2026-08-07: accessibility + end-of-run summary --- */
.rrt-container :focus-visible,
.rrt-container button:focus-visible,
.rrt-container input:focus-visible,
.rrt-container select:focus-visible {
    outline: 3px solid #1b64d1;
    outline-offset: 2px;
    border-radius: 4px;
}
@media (prefers-reduced-motion: reduce) {
    .rrt-container *,
    .rrt-container *::before,
    .rrt-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}
.rrt-container .rrt-summary-panel {
    background: #ffffff;
    border: 2px solid #0f1d3a;
    border-radius: 10px;
    padding: 18px 20px;
    margin: 18px 0;
}
.rrt-container .rrt-summary-panel h3 {
    margin: 0 0 12px 0;
    color: #0f1d3a;
}
.rrt-container .rrt-score-row {
    display: flex;
    align-items: center;
    gap: 14px;
    flex-wrap: wrap;
    margin-bottom: 10px;
}
.rrt-container .rrt-score-badge {
    font-size: 2rem;
    font-weight: 800;
    color: #0f1d3a;
    line-height: 1;
}
.rrt-container .rrt-score-max {
    font-size: 1rem;
    font-weight: 600;
    color: #4a5568;
    margin-left: 2px;
}
.rrt-container .rrt-score-label {
    font-size: 1rem;
    font-weight: 700;
    color: #241a05;
    background: #e7c977;
    border-radius: 999px;
    padding: 4px 14px;
}
.rrt-container .rrt-summary-text {
    color: #22314f;
    line-height: 1.55;
}

