                var allBlank = (!eqEl || eqEl.value === '') && (!bdEl || bdEl.value === '') && (!caEl || caEl.value === '');
                var sumEl = document.getElementById(s + 'Sum');
                if (sumEl) {
                    sumEl.textContent = sum + '%';
                    if (Math.abs(sum - 100) > 0.5) sumEl.classList.add('bad');
                    else sumEl.classList.remove('bad');
                }
                if (allBlank) return;
                var totalForBar = sum > 0 ? sum : 1;
                var barEq = document.getElementById(s + 'BarEquity');
                var barBd = document.getElementById(s + 'BarBonds');
                var barCa = document.getElementById(s + 'BarCash');
                if (barEq) barEq.style.width = (eq * 100 / totalForBar) + '%';
                if (barBd) barBd.style.width = (bd * 100 / totalForBar) + '%';
                if (barCa) barCa.style.width = (ca * 100 / totalForBar) + '%';
                var eqPct = document.getElementById(s + 'EquityPct');
                var bdPct = document.getElementById(s + 'BondsPct');
                var caPct = document.getElementById(s + 'CashPct');
                if (eqPct) eqPct.textContent = eq;
                if (bdPct) bdPct.textContent = bd;
                if (caPct) caPct.textContent = ca;
            });
        }

        _portfolioMultiplier(p, m) {
            var eq = (p.equity || 0) / 100;
            var gov = ((p.bonds || 0) / 100) * 0.5;
            var corp = ((p.bonds || 0) / 100) * 0.5;
            var ca = (p.cash || 0) / 100;
            return eq * m.equity + gov * m.govBond + corp * m.corpBond + ca * m.cash;
        }

        _portfolioValue(p, m) {
            return this.STARTING_CAPITAL * this._portfolioMultiplier(p, m);
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod;
            var self = this;

            if (period === 1 || period === 3) {
                var blank = false;
                this.SIBLINGS.forEach(function(s) {
                    ['Equity', 'Bonds', 'Cash'].forEach(function(k) {
                        var el = document.getElementById(s + k + 'Input');
                        if (!el || String(el.value).trim() === '') blank = true;
                    });
                });
                if (blank) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('alloc_blank_warning'), 'warning'
                    );
                    return false;
                }
                var bad = false;
                this.SIBLINGS.forEach(function(s) {
                    var eqEl = document.getElementById(s + 'EquityInput');
                    var bdEl = document.getElementById(s + 'BondsInput');
                    var caEl = document.getElementById(s + 'CashInput');
                    var eq = eqEl ? parseFloat(eqEl.value) : NaN;
                    var bd = bdEl ? parseFloat(bdEl.value) : NaN;
                    var ca = caEl ? parseFloat(caEl.value) : NaN;
                    if (isNaN(eq) || isNaN(bd) || isNaN(ca)) { bad = true; return; }
                    if (eq < 0 || bd < 0 || ca < 0 || eq > 100 || bd > 100 || ca > 100) { bad = true; return; }
                    var sum = eq + bd + ca;
                    if (Math.abs(sum - 100) > 0.5) bad = true;
                    decisions[s + 'Equity'] = eq;
                    decisions[s + 'Bonds'] = bd;
                    decisions[s + 'Cash'] = ca;
                });
                if (bad) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('alloc_warning'), 'warning'
                    );
                    return false;
                }
                return true;
            } else if (period === 2) {
                this.SIBLINGS.forEach(function(s) {
                    var sel = document.getElementById(s + 'Action');
                    if (sel) decisions[s + 'Action'] = sel.value;
                });
                return true;
            }
            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var self = this;
            var results = { period: period };

            if (period === 1) {
                this.SIBLINGS.forEach(function(s) {
                    state.domainState.portfolios[s] = {
                        equity: state.decisions[s + 'Equity'],
                        bonds: state.decisions[s + 'Bonds'],
                        cash: state.decisions[s + 'Cash']
                    };
                    state.domainState.troughValues[s] = self._portfolioValue(state.domainState.portfolios[s], self.SCENARIO.trough);
                    state.domainState[s + 'ValueHistory'] = [self.STARTING_CAPITAL, self.STARTING_CAPITAL];
                    state.domainState.finalValues[s] = self.STARTING_CAPITAL;
                });
                state.domainState.round1Done = true;

                results.phase = 'build';
                results.saraEquity = state.decisions.saraEquity;
                results.saraBonds = state.decisions.saraBonds;
                results.saraCash = state.decisions.saraCash;
                results.mateoEquity = state.decisions.mateoEquity;
                results.mateoBonds = state.decisions.mateoBonds;
                results.mateoCash = state.decisions.mateoCash;
                results.carmenEquity = state.decisions.carmenEquity;
                results.carmenBonds = state.decisions.carmenBonds;
                results.carmenCash = state.decisions.carmenCash;
                results.saraTrough = state.domainState.troughValues.sara;
                results.mateoTrough = state.domainState.troughValues.mateo;
                results.carmenTrough = state.domainState.troughValues.carmen;
                results.summaryLine = window.mySimulation.t('history_round1');
            } else if (period === 2) {
                this.SIBLINGS.forEach(function(s) {
                    state.domainState.actions[s] = state.decisions[s + 'Action'];
                });

                var comparisons = {};
                this.SIBLINGS.forEach(function(s) {
                    var p = state.domainState.portfolios[s];
                    var trough = state.domainState.troughValues[s];
                    var holdY5 = self._portfolioValue(p, self.SCENARIO.year5);
                    var sellY5 = trough * 1.0;
                    var equityGain = self.BUY_AMOUNT * (self.SCENARIO.year5.equity / self.SCENARIO.trough.equity);
                    var buyY5 = holdY5 + equityGain - self.BUY_AMOUNT;
                    comparisons[s] = { hold: holdY5, sell: sellY5, buy: buyY5, trough: trough };
                });
                state.domainState.comparisons = comparisons;

                this.SIBLINGS.forEach(function(s) {
                    var act = state.domainState.actions[s];
                    state.domainState.finalValues[s] = comparisons[s][act];
                    state.domainState[s + 'ValueHistory'] = [
                        self.STARTING_CAPITAL,
                        comparisons[s].trough,
                        comparisons[s][act]
                    ];
                });
                state.domainState.round2Done = true;

                results.phase = 'crash';
                results.saraAction = state.domainState.actions.sara;
                results.mateoAction = state.domainState.actions.mateo;
                results.carmenAction = state.domainState.actions.carmen;
                results.saraFinal = state.domainState.finalValues.sara;
                results.mateoFinal = state.domainState.finalValues.mateo;
                results.carmenFinal = state.domainState.finalValues.carmen;
                results.saraHold = comparisons.sara.hold;
                results.saraSell = comparisons.sara.sell;
                results.saraBuy = comparisons.sara.buy;
                results.mateoHold = comparisons.mateo.hold;
                results.mateoSell = comparisons.mateo.sell;
                results.mateoBuy = comparisons.mateo.buy;
                results.carmenHold = comparisons.carmen.hold;
                results.carmenSell = comparisons.carmen.sell;
                results.carmenBuy = comparisons.carmen.buy;
                results.summaryLine = window.mySimulation.t('history_round2');
            } else if (period === 3) {
                this.SIBLINGS.forEach(function(s) {
                    state.domainState.portfolios[s] = {
                        equity: state.decisions[s + 'Equity'],
                        bonds: state.decisions[s + 'Bonds'],
                        cash: state.decisions[s + 'Cash']
                    };
                    state.domainState.troughValues[s] = self._portfolioValue(state.domainState.portfolios[s], self.SCENARIO.trough);
                    state.domainState.finalValues[s] = self._portfolioValue(state.domainState.portfolios[s], self.SCENARIO.year5);
                    state.domainState[s + 'ValueHistory'] = [
                        self.STARTING_CAPITAL,
                        state.domainState.troughValues[s],
                        state.domainState.finalValues[s]
                    ];
                });
                state.domainState.round3Done = true;
                state.domainState.runComplete = true;
                var t3 = 0;
                this.SIBLINGS.forEach(function(s) { t3 += state.domainState.finalValues[s] || 0; });
                var sc3 = this._composite(state.domainState.portfolios, state.domainState.actions, t3);
                state.domainState.overallScore = sc3;
                state.domainState.totalScore = sc3;
                state.domainState.performanceKey = this._performanceKey(sc3);
                results.overallScore = sc3;
                results.totalScore = sc3;

                results.phase = 'calibrate';
                results.saraEquity = state.decisions.saraEquity;
                results.saraBonds = state.decisions.saraBonds;
                results.saraCash = state.decisions.saraCash;
                results.mateoEquity = state.decisions.mateoEquity;
                results.mateoBonds = state.decisions.mateoBonds;
                results.mateoCash = state.decisions.mateoCash;
                results.carmenEquity = state.decisions.carmenEquity;
                results.carmenBonds = state.decisions.carmenBonds;
                results.carmenCash = state.decisions.carmenCash;
                results.saraFinal = state.domainState.finalValues.sara;
                results.mateoFinal = state.domainState.finalValues.mateo;
                results.carmenFinal = state.domainState.finalValues.carmen;
                results.summaryLine = window.mySimulation.t('history_round3');
            }

            // Platform score 0 to 100: the sim composite (_composite, as in getPerformanceSummary) on the play so far; behaviour points count once the crash round is decided
            var dsNow = state.domainState;
            var totalNow = 0;
            this.SIBLINGS.forEach(function(s) { totalNow += (dsNow.finalValues && dsNow.finalValues[s]) || 0; });
            var actionsNow = dsNow.round2Done ? dsNow.actions : { sara: 'pending', mateo: 'pending', carmen: 'pending' };
            var runningScore = this._composite(dsNow.portfolios, actionsNow, totalNow);
            var prevPerf = (dsNow.performance && typeof dsNow.performance === 'object') ? dsNow.performance : {};
            state.domainState.performance = Object.assign({}, prevPerf, { overallScore: runningScore });

            setTimeout(function() {
                var nextState = window.mySimulation.state;
                if ((nextState.currentPeriod || 1) === 3 && !(nextState.domainState && nextState.domainState.round3Done)) self._clearAllocInputs();
                self._updateBriefing(nextState);
                self._updateSiblingCards(nextState);
                self._updateTroughDisplay(nextState);
                self._renderComparePanel(nextState);
                self._renderSummaryPanel(nextState);
                self._wireSumListeners();
            }, 500);

            return results;
        }

        _clearAllocInputs() {
            this.SIBLINGS.forEach(function(s) {
                ['Equity', 'Bonds', 'Cash'].forEach(function(k) {
                    var el = document.getElementById(s + k + 'Input');
                    if (el) el.value = '';
                });
            });
        }

        _updateSiblingCards(state) {
            if (!state || !state.domainState || !state.domainState.portfolios) return;
            var period = state.currentPeriod || 1;
            var self = this;
            this.SIBLINGS.forEach(function(s) {
                var p = state.domainState.portfolios[s];
                var eqEl = document.getElementById(s + 'EquityPct');
                var bdEl = document.getElementById(s + 'BondsPct');
                var caEl = document.getElementById(s + 'CashPct');
                var barEq = document.getElementById(s + 'BarEquity');
                var barBd = document.getElementById(s + 'BarBonds');
                var barCa = document.getElementById(s + 'BarCash');
                if (!state.domainState.round1Done) {
                    if (eqEl) eqEl.textContent = '—';
                    if (bdEl) bdEl.textContent = '—';
                    if (caEl) caEl.textContent = '—';
                    if (barEq) barEq.style.width = '0%';
                    if (barBd) barBd.style.width = '0%';
                    if (barCa) barCa.style.width = '0%';
                } else {
                    if (eqEl) eqEl.textContent = p.equity;
                    if (bdEl) bdEl.textContent = p.bonds;
                    if (caEl) caEl.textContent = p.cash;
                    if (barEq) barEq.style.width = p.equity + '%';
                    if (barBd) barBd.style.width = p.bonds + '%';
                    if (barCa) barCa.style.width = p.cash + '%';
                }

                var valEl = document.getElementById(s + 'Value');
                var deltaEl = document.getElementById(s + 'Delta');
                var v = state.domainState.finalValues[s] || self.STARTING_CAPITAL;
                if (valEl) valEl.textContent = '€' + Math.round(v).toLocaleString();
                if (deltaEl) {
                    deltaEl.classList.remove('up', 'down');
                    if (period <= 1) {
                        deltaEl.textContent = '';
                    } else {
                        var diff = v - self.STARTING_CAPITAL;
                        var pct = (diff / self.STARTING_CAPITAL) * 100;
                        var sign = diff >= 0 ? '+' : '';
                        deltaEl.textContent = sign + '€' + Math.round(diff).toLocaleString() + ' (' + sign + pct.toFixed(1) + '%)';
                        deltaEl.classList.add(diff >= 0 ? 'up' : 'down');
                    }
                }
            });
        }

        _updateTroughDisplay(state) {
            if (!state || !state.domainState) return;
            var self = this;
            this.SIBLINGS.forEach(function(s) {
                var trough = state.domainState.troughValues[s] || self.STARTING_CAPITAL;
                var loss = ((trough - self.STARTING_CAPITAL) / self.STARTING_CAPITAL) * 100;
                var tEl = document.getElementById(s + 'TroughDisplay');
                var lEl = document.getElementById(s + 'LossDisplay');
                if (tEl) tEl.textContent = '€' + Math.round(trough).toLocaleString();
                if (lEl) lEl.textContent = (loss >= 0 ? '+' : '') + loss.toFixed(1) + '%';
            });
        }

        _renderComparePanel(state) {
            var panel = document.getElementById('comparePanel');
            if (!panel) return;
            var period = state.currentPeriod || 1;
            if (period < 3 || !state.domainState || !state.domainState.comparisons) {
                panel.style.display = 'none';
                return;
            }
            panel.style.display = 'block';
            var grid = document.getElementById('compareGrid');
            if (!grid) return;
            var comp = state.domainState.comparisons;
            var actions = state.domainState.actions;
            var fmt = function(v) { return '€' + Math.round(v).toLocaleString(); };
            var labels = {
                hold: window.mySimulation.t('opt_hold_short'),
                sell: window.mySimulation.t('opt_sell_short'),
                buy:  window.mySimulation.t('opt_buy_short')
            };
            var siblingLabels = { sara: 'Sara', mateo: 'Mateo', carmen: 'Carmen' };
            var html = '';
            this.SIBLINGS.forEach(function(s) {
                var c = comp[s];
                var values = [
                    { key: 'hold', val: c.hold },
                    { key: 'sell', val: c.sell },
                    { key: 'buy',  val: c.buy }
                ];
                var maxV = Math.max(c.hold, c.sell, c.buy);
                var minV = Math.min(c.hold, c.sell, c.buy);
                html += '<div class="rrt-compare-card rrt-sibling-' + s + '">';
                html += '<div class="rrt-compare-name">' + siblingLabels[s] + '</div>';
                values.forEach(function(v) {
                    var cls = '';
                    if (Math.abs(v.val - maxV) < 0.01) cls += ' best';
                    if (Math.abs(v.val - minV) < 0.01) cls += ' worst';
                    if (v.key === actions[s]) cls += ' chosen';
                    html += '<div class="rrt-compare-row' + cls + '"><span>' + labels[v.key] + '</span><span>' + fmt(v.val) + '</span></div>';
                });
                html += '</div>';
            });
            grid.innerHTML = html;
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var builderPanel = document.getElementById('builderPanel');
            var crashPanel = document.getElementById('crashPanel');
            var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var actionsRow = document.getElementById('rrtActions');
            var done = !!(state.domainState && state.domainState.runComplete) || period > 3;

            if (done) {
                if (titleEl) titleEl.textContent = t('summary_title');
                if (textEl) textEl.innerHTML = t('summary_brief');
                if (builderPanel) builderPanel.style.display = 'none';
                if (crashPanel) crashPanel.style.display = 'none';
                if (actionsRow) actionsRow.style.display = 'none';
                this._renderSummaryPanel(state);
                return;
            }
            if (actionsRow) actionsRow.style.display = '';

            if (period === 1) {
                if (titleEl) titleEl.textContent = t('round1_title');
                if (textEl) textEl.innerHTML = t('round1_brief');
                if (builderPanel) builderPanel.style.display = 'block';
                if (crashPanel) crashPanel.style.display = 'none';
            } else if (period === 2) {
                if (titleEl) titleEl.textContent = t('round2_title');
                if (textEl) textEl.innerHTML = t('round2_brief');
                if (builderPanel) builderPanel.style.display = 'none';
                if (crashPanel) crashPanel.style.display = 'block';
            } else if (period === 3) {
                if (titleEl) titleEl.textContent = t('round3_title');
                if (textEl) textEl.innerHTML = t('round3_brief');
                if (builderPanel) builderPanel.style.display = 'block';
                if (crashPanel) crashPanel.style.display = 'none';
            } else {
                if (titleEl) titleEl.textContent = t('summary_title');
                if (textEl) textEl.innerHTML = t('summary_brief');
                if (builderPanel) builderPanel.style.display = 'none';
                if (crashPanel) crashPanel.style.display = 'none';
            }
        }

        _allocFit(portfolios) {
            // Distance from an age appropriate equity band, per sibling, 0 to 1 each.
            var self = this;
            var total = 0;
            this.SIBLINGS.forEach(function(s) {
                var p = (portfolios && portfolios[s]) || { equity: 0 };
                if (p.equity === null || p.equity === undefined || p.equity === '' || !isFinite(p.equity)) return;
                var eq = p.equity || 0;
                var band = self.EQUITY_BANDS[s];
                var miss = 0;
                if (eq < band.lo) miss = band.lo - eq;
                else if (eq > band.hi) miss = eq - band.hi;
                var fit = 1 - Math.min(1, miss / 40);
                total += fit;
            });
            return total / this.SIBLINGS.length;
        }

        _behaviourScore(actions) {
            var self = this;
            var pts = 0;
            this.SIBLINGS.forEach(function(s) {
                var a = (actions && actions[s]) || 'hold';
                var v = self.BEHAVIOUR_POINTS[a];
                pts += (v === undefined ? 0 : v);
            });
            return pts;
        }

        _composite(portfolios, actions, totalFinal) {
            var w = this.SCORE_WEIGHTS;
            var alloc = this._allocFit(portfolios) * w.alloc;
            var behaviour = this._behaviourScore(actions);
            var span = this.WEALTH_CEIL - this.WEALTH_FLOOR;
            var norm = span > 0 ? (totalFinal - this.WEALTH_FLOOR) / span : 0;
            norm = Math.max(0, Math.min(1, norm));
            var wealth = norm * w.wealth;
            var score = alloc + behaviour + wealth;

            // The verdict and the number have to agree. Selling at the trough is the
            // failure state this simulation exists to teach, so it caps the score.
            var sold = 0;
            var self = this;
            this.SIBLINGS.forEach(function(s) {
                if (actions && actions[s] === 'sell') sold++;
            });
            if (sold >= 3) score = Math.min(score, this.SELL_CAP_ALL);
            else if (sold >= 1) score = Math.min(score, this.SELL_CAP_ANY);

            return Math.max(0, Math.min(100, Math.round(score)));
        }

        _performanceKey(score) {
            if (score >= 85) return 'excellent';
            if (score >= 70) return 'strong';
            if (score >= 55) return 'developing';
            return 'beginner';
        }

        _renderSummaryPanel(state) {
            var panel = document.getElementById('rrtSummaryPanel');
            if (!panel) return;
            if (!state || !state.domainState || !state.domainState.runComplete) {
                panel.style.display = 'none';
                return;
            }
            var ds = state.domainState;
            var totalFinal = 0;
            var self = this;
            this.SIBLINGS.forEach(function(s) { totalFinal += (ds.finalValues && ds.finalValues[s]) || 0; });
            var score = this._composite(ds.portfolios, ds.actions, totalFinal);
            var key = this._performanceKey(score);
            var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var valEl = document.getElementById('rrtScoreValue');
            var labEl = document.getElementById('rrtScoreLabel');
            var txtEl = document.getElementById('rrtSummaryText');
            if (valEl) valEl.textContent = score;
            if (labEl) labEl.textContent = t('perf_' + key);
            if (txtEl) txtEl.innerHTML = this._debriefHtml(ds, score, key, totalFinal);
            panel.style.display = 'block';
        }

        _debriefHtml(ds, score, key, totalFinal) {
            var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var sold = [], held = [], bought = [];
            var names = { sara: 'Sara', mateo: 'Mateo', carmen: 'Carmen' };
            this.SIBLINGS.forEach(function(s) {
                var a = (ds.actions && ds.actions[s]) || 'hold';
                if (a === 'sell') sold.push(names[s]);
                else if (a === 'buy') bought.push(names[s]);
                else held.push(names[s]);
            });
            var parts = [];
            parts.push(t('debrief_total').replace('{total}', 'EUR ' + Math.round(totalFinal).toLocaleString()));
            if (sold.length) parts.push(t('debrief_sold').replace('{who}', sold.join(', ')));
            if (bought.length) parts.push(t('debrief_bought').replace('{who}', bought.join(', ')));
            if (!sold.length && !bought.length) parts.push(t('debrief_all_held'));
            parts.push(t('debrief_' + key));
            return parts.join(' ');
        }

        formatCompletionMessage(summary) {
            var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var s = summary || {};
            var score = (s.overallScore === undefined || s.overallScore === null) ? 0 : s.overallScore;
            var label = s.performanceLabel || t('perf_' + (s.performance || 'beginner'));
            var head = t('completion_head')
                .replace('{score}', score)
                .replace('{label}', label)
                .replace('{total}', 'EUR ' + Math.round(s.totalFinal || 0).toLocaleString());
            var lines = [head];
            (s.insights || []).forEach(function(i) { lines.push(i); });
            return lines.join('\n\n');
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            /* the chart follows a language switch: the framework re-reads getChartData, which relabels the title and legend */
            if (!this._chartLangBound && typeof document !== 'undefined') {
                this._chartLangBound = true;
                document.addEventListener('express:langchanged', function() {
                    try { if (window.mySimulation && typeof window.mySimulation.updateCharts === 'function') window.mySimulation.updateCharts(); } catch (e) {}
                });
            }
        }

        /* chart title and legend in the current language, looked up at render time; English if the framework has no text yet */
        _chartText(k) {
            var v = null;
            try { if (window.mySimulation && typeof window.mySimulation.t === 'function') v = window.mySimulation.t(k); } catch (e) {}
            if (typeof v !== 'string' || !v || v === k) {
                if (!this._enChartT) { try { this._enChartT = this.getTranslations().en || {}; } catch (e) { this._enChartT = {}; } }
                v = this._enChartT[k] || k;
            }
            return v;
        }

        _liveChart(id) {
            var sim = window.mySimulation;
            if (sim && sim.charts && sim.charts[id]) return sim.charts[id];
            if (sim && sim.uiManager && sim.uiManager.charts && sim.uiManager.charts[id]) return sim.uiManager.charts[id];
            if (typeof Chart !== 'undefined' && typeof Chart.getChart === 'function') return Chart.getChart(id) || null;
            return null;
        }

        _labelCharts() {
            var ch = this._liveChart('portfolioChart');
            var o = ch && ch.options;
