        getChartData(state) {
            var period = state.currentPeriod || 1;
            var labels;
            var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var ds = state.domainState || {};

            if (period <= 1 || !ds.round1Done) {
                labels = [t('chart_start'), t('chart_today')];
            } else if (period === 2 && !ds.round2Done) {
                labels = [t('chart_start'), t('chart_pre_crash')];
            } else {
                labels = [t('chart_start'), t('chart_trough'), t('chart_year5')];
            }

            var sH = ds.saraValueHistory || [this.STARTING_CAPITAL];
            var mH = ds.mateoValueHistory || [this.STARTING_CAPITAL];
            var cH = ds.carmenValueHistory || [this.STARTING_CAPITAL];

            var trim = function(arr) {
                var out = arr.slice(0, labels.length);
                while (out.length < labels.length) out.push(out[out.length - 1] || 10000);
                return out;
            };

            var c = this._chartText.bind(this);
            this._labelCharts();
            return {
                portfolioChart: {
                    labels: labels,
                    datasets: [
                        { label: c('chart_sara'),   data: trim(sH) },
                        { label: c('chart_mateo'),  data: trim(mH) },
                        { label: c('chart_carmen'), data: trim(cH) }
                    ]
                }
            };
        }

        getHint(state, results) {
            if (!state || !state.domainState) return null;
            var period = state.currentPeriod || 1;

            if (period === 2 && state.domainState.round1Done) {
                if (state.domainState.portfolios.carmen.equity >= 60) {
                    return window.mySimulation.t('hint_carmen_aggressive');
                }
                if (state.domainState.portfolios.sara.equity <= 40) {
                    return window.mySimulation.t('hint_sara_conservative');
                }
                return window.mySimulation.t('hint_round2_general');
            }

            if (period === 3 && state.domainState.round2Done) {
                var sold = 0;
                this.SIBLINGS.forEach(function(s) {
                    if (state.domainState.actions[s] === 'sell') sold++;
                });
                if (sold > 0) return window.mySimulation.t('hint_sold_at_trough');

                var bought = 0;
                this.SIBLINGS.forEach(function(s) {
                    if (state.domainState.actions[s] === 'buy') bought++;
                });
                if (bought >= 2) return window.mySimulation.t('hint_bought_strong');

                return window.mySimulation.t('hint_round3_general');
            }

            return null;
        }

        getHistoryTableConfig() {
            var fmtMoney = function(v) {
                if (v === undefined || v === null) return '—';
                return '€' + Math.round(v).toLocaleString();
            };
            return [
                { key: 'period', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.summaryLine', label: 'Phase', i18nKey: 'col_phase' },
                { key: 'results.saraFinal',   label: 'Sara',   i18nKey: 'col_sara',   formatter: fmtMoney },
                { key: 'results.mateoFinal',  label: 'Mateo',  i18nKey: 'col_mateo',  formatter: fmtMoney },
                { key: 'results.carmenFinal', label: 'Carmen', i18nKey: 'col_carmen', formatter: fmtMoney }
            ];
        }

        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = window.mySimulation.t.bind(window.mySimulation);
            var self = this;
            var insights = [];
            var totalFinal = 0;
            var lastByPhase = {};

            history.forEach(function(h) {
                if (h.results && h.results.phase) lastByPhase[h.results.phase] = h.results;
            });

            var crash = lastByPhase.crash;
            var calibrate = lastByPhase.calibrate || lastByPhase.crash;

            if (calibrate) {
                totalFinal = (calibrate.saraFinal || 0) + (calibrate.mateoFinal || 0) + (calibrate.carmenFinal || 0);
            }

            var actions = {};
            if (crash) {
                actions = { sara: crash.saraAction, mateo: crash.mateoAction, carmen: crash.carmenAction };
                var sold = 0, held = 0, bought = 0;
                ['saraAction', 'mateoAction', 'carmenAction'].forEach(function(k) {
                    if (crash[k] === 'sell') sold++;
                    else if (crash[k] === 'hold') held++;
                    else if (crash[k] === 'buy') bought++;
                });
                if (sold === 0 && bought === 0) insights.push(t('insight_all_held'));
                if (sold === 0 && bought >= 1) insights.push(t('insight_some_bought'));
                if (sold >= 1) insights.push(t('insight_some_sold'));
                if (bought === 3) insights.push(t('insight_all_bought'));
            }

            var portfolios = {};
            var alloc = lastByPhase.calibrate || lastByPhase.build;
            if (alloc) {
                this.SIBLINGS.forEach(function(s) {
                    portfolios[s] = {
                        equity: alloc[s + 'Equity'] || 0,
                        bonds: alloc[s + 'Bonds'] || 0,
                        cash: alloc[s + 'Cash'] || 0
                    };
                });
            }

            insights.push(t('insight_capacity_vs_tolerance'));
            insights.push(t('insight_ulysses'));

            var score = this._composite(portfolios, actions, totalFinal);
            var key = this._performanceKey(score);
            var label = t('perf_' + key);

            return {
                totalFinal: totalFinal,
                // Stable identifier for analytics; the localized string is performanceLabel.
                performance: key,
                performanceKey: key,
                performanceLabel: label,
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                allocationFit: Math.round(self._allocFit(portfolios) * 100),
                behaviourScore: self._behaviourScore(actions),
                insights: insights
            };
        }

